            prerelease_part = v_without_build[v_without_build.index('-') + 1:]
        else:
            main_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = main_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # pre1 and pre2 are either None or a list of identifiers
        # A version without pre-release has higher precedence than one with
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # no pre-release sorts after pre-release
        if pre2 is None:
            return -1  # pre-release sorts before no pre-release

