            if is_digit1 and is_digit2:
                # Both numeric, compare numerically
                cmp = int(id1) - int(id2)
                if cmp != 0:
                    return -1 if cmp < 0 else 1
            elif is_digit1:
                # Numeric sorts before non-numeric
                return -1
            elif is_digit2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric, compare by ASCII order
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        return 0

    def compare_versions(v1, v2):
        parsed1 = parse_version(v1)
        parsed2 = parse_version(v2)

        # Compare MAJOR, MINOR, PATCH
        if parsed1[0] != parsed2[0]:
            return -1 if parsed1[0] < parsed2[0] else 1
        if parsed1[1] != parsed2[1]:
            return -1 if parsed1[1] < parsed2[1] else 1
        if parsed1[2] != parsed2[2]:
            return -1 if parsed1[2] < parsed2[2] else 1

        # Compare pre-release
        cmp = compare_prerelease(parsed1[3], parsed2[3])
        return cmp

    from functools import cmp_to_key
    return sorted(versions, key=cmp_to_key(compare_versions))

